  var d0 int64= int64(int64(uint64(n) >> uint(int64(12))) & int64(15));
  var d1 int64= int64(int64(uint64(n) >> uint(int64(8))) & int64(15));
  var d2 int64= int64(int64(uint64(n) >> uint(int64(4))) & int64(15));
  var d3 int64= int64(n & int64(15));
  return ((digits[d0:(d0 + int64(1))] + digits[d1:(d1 + int64(1))]) + digits[d2:(d2 + int64(1))]) + digits[d3:(d3 + int64(1))]
